class _ProblemRequired(TypedDict):
    #: URI reference that identifies the problem type.
    type: str
    #: Short summary of the problem type.
    title: str
    #: HTTP status code.
    status: int


class Problem(_ProblemRequired, total=False):
    """RFC 9457 problem details, served as application/problem+json."""

    #: Explanation specific to this occurrence.
    detail: str
    #: URI reference that identifies this occurrence.
    instance: str


class _RefusalProblemRequired(TypedDict):
    #: URI reference that identifies the problem type.
    type: str
    #: Short summary of the problem type.
    title: str
    #: HTTP status code.
    status: int
    refusal: Refusal
    #: Why the request was refused, in sentence case.
    reason: str


class RefusalProblem(_RefusalProblemRequired, total=False):
    """Problem details for a refusal. Returned with status 422."""

    #: Explanation specific to this occurrence.
    detail: str
    #: URI reference that identifies this occurrence.
    instance: str
    #: The rule that refused the request, such as a separation of duties rule.
    rule: str


class _ValidationProblemRequired(TypedDict):
    #: URI reference that identifies the problem type.
    type: str
    #: Short summary of the problem type.
    title: str
    #: HTTP status code.
    status: int
    #: Invalid members of the request.
    errors: List[Dict[str, Any]]


class ValidationProblem(_ValidationProblemRequired, total=False):
    """Problem details for a request that failed schema validation. Returned with status 422."""

    #: Explanation specific to this occurrence.
    detail: str
    #: URI reference that identifies this occurrence.
    instance: str


class HomeSummary(TypedDict):
    """The org dashboard: my work, gate readiness and alerts for the caller."""

    #: Records assigned to the caller that are not Complete or Canceled.
    open_work_count: int
    #: Assigned records that are Blocked.
    blocked_work_count: int
    #: Projects with an unsatisfied blocking criterion at the next gate.
    projects_at_risk_count: int
    #: Unread alerts.
    alert_count: int
    committed_spend: MoneyTotal


class MoneyTotal(TypedDict):
    """A money aggregate that never coerces unpriced inputs to zero."""

    #: Sum of priced inputs in minor units; null when every input is unpriced.
    total_minor: Optional[int]
    #: ISO 4217 currency code of every money field.
    currency: str
    #: Number of inputs that are unpriced (null) and were not summed.
    unpriced_count: int


class ProjectPage(TypedDict):
    """One page of results with a cursor to the next page."""

    #: Items on this page, in the documented default order.
    data: List[Project]
    #: Opaque cursor for the next page; null on the last page.
    next_cursor: Optional[str]


class Project(TypedDict):
    """A production project. Jurisdiction is resolved at gate 1."""

    #: Identifier of the project.
    id: str
    #: Identifier of the owning organization, derived from the parent row and never accepted from the caller.
    org_id: str
    #: When the row was created.
    created_at: str
    #: Identifier of the person who created the row; null when a seed, platform or system process created it.
    created_by: Optional[str]
    #: When the row was last updated.
    updated_at: str
    #: Identifier of the person who last updated the row; null when a seed, platform or system process updated it.
    updated_by: Optional[str]
    #: Project key, chosen by the caller and unique in the organization; it addresses the project in Atlas URLs.
    project_key: str
    #: Project name, Title Case.
    name: str
    #: Project description.
    description: Optional[str]
    #: Identifier of the workspace.
    workspace_id: Optional[str]
    jurisdiction_id: JurisdictionId
    region_code: RegionCode
    tier_code: Optional[TierCode]
    current_phase_code: PhaseCode
    #: Project lifecycle state. A Title Case value from the lifecycle's database enum.
    project_state: str
    #: Base currency of the project.
    currency: str
    #: First show day.
    starts_on: Optional[str]
    #: Last show day.
    ends_on: Optional[str]
    #: IANA time zone of the project; local times are entered in it.
    time_zone: str
    #: Identifier of the primary venue of the project.
    venue_id: Optional[str]
    #: Identifier of the client counterparty the project is produced for.
    client_counterparty_id: Optional[str]
    #: Production lifecycle state, which runs beside the project state; changes only through its transition RPC. A Title Case value from the lifecycle's database enum.
    production_state: str
    #: When the project was archived; archived projects leave the default lists.
    archived_at: Optional[str]


