class Record(TypedDict):
    """A record of any of the 26 kinds. Kind-specific attributes live in 1:1 extension tables keyed by `record_id`."""

    #: Identifier of the record.
    id: str
    #: Identifier of the owning organization, derived from the parent row and never accepted from the caller.
    org_id: str
    #: When the row was created.
    created_at: str
    #: Identifier of the person who created the row; null when a seed, platform or system process created it.
    created_by: Optional[str]
    #: When the row was last updated.
    updated_at: str
    #: Identifier of the person who last updated the row; null when a seed, platform or system process updated it.
    updated_by: Optional[str]
    #: Display key issued by `next_sequence`.
    record_key: str
    record_kind: RecordKind
    record_subtype: RecordSubtype
    record_class: RecordClass
    record_state: RecordState
    #: Title, validated against the kind's title grammar on write.
    title: str
    #: Identifier of the scope node.
    scope_node_id: str
    phase_code: PhaseCode
    urid: UridAtAnyGrain
    xyz: Xyz
    #: Identifier of the owning person or organization.
    owner_party_id: Optional[str]
    #: Identifier of the accountable person or organization.
    accountable_party_id: Optional[str]
    #: Start of the record window.
    starts_at: Optional[str]
    #: End of the record window.
    ends_at: Optional[str]
    #: Due instant.
    due_at: Optional[str]
    #: The named blocker; required when Blocked.
    blocker_text: Optional[str]
    #: Replan reason; required when Deferred.
    replan_reason: Optional[str]
    #: External role types that may see the record; empty means internal only. Stored as junction rows, presented as a set.
    external_visibility: List[ExternalRoleType]


